import {esc,icon} from './ui.mjs';
import {ensureAigcStyle} from './aigc-detection.mjs';
import {createDetectionProgress,ensureDetectionProgressStyle} from './detection-progress.mjs';
import {createDetectionWorkflow} from './detection-workflow.mjs';
import {detectionPriceText,detectionPriceSnapshot,createDetectionQuote} from './detection-billing.mjs';
import {validatePaperUpload} from './paper-upload-policy.mjs';
import {importWorkspaceDocument} from './document-import.mjs';
import {createDocumentServiceClient,watchDocumentService} from './document-services-client.mjs';
export function mountCombinedDetection({container,fetchImpl,importDocument=importWorkspaceDocument,pollInterval=2200}={}){
 const doc=container.ownerDocument,win=doc.defaultView,$=s=>container.querySelector(s);let alive=true,owner=null,cap={},text='',title='',item=null,busy=false,timer=null,intent=null,workflow,progress,priceQuote=null,unwatch=()=>{};
 const current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});ensureAigcStyle(doc);ensureDetectionProgressStyle(doc);
 const status=message=>{if(current())$('[data-joint-status]').textContent=message;};
 const stop=()=>{win.clearTimeout(timer);timer=null;};
 const controls=()=>{if(!current())return;const active=item?.status==='running';$('[data-joint-file]').disabled=busy||active;$('[data-joint-start]').disabled=busy||active||!text||!(priceQuote?.ready||priceQuote?.insufficient);$('[data-joint-cancel]').hidden=!active;$('[data-joint-cancel]').disabled=busy;};
 async function checkOwner(){const me=await client.request('/auth/me');if(me.user?.id!==owner){text='';title='';item=null;intent=null;stop();progress?.dispose();container.innerHTML='<p role="alert">登录账户已变化，请重新进入联合检测。</p>';alive=false;throw Error('登录账户已变化，请重新进入本功能。');}}
 function render(){controls();if(!item)return;const active=item.status==='running';workflow.update({phase:active?'running':item.status==='completed'?'complete':'failed',hasText:!!text,valid:!!text,hasTask:true,hasReport:item.status==='completed'});
  if(active){progress.update({state:'running',startedAt:item.createdAt});stop();timer=win.setTimeout(()=>void run(()=>read(item.id)),pollInterval);return;}
  progress.clear();const children=Array.isArray(item.children)?item.children:[],partial=item.partial===true||children.some(c=>c.partial===true);const heading=item.status==='completed'?(partial?'两份报告已生成，部分内容待核对':'两份检测报告已完成'):'本次联合检测未完成';
  const cards=[['similarity','重复率报告','查看原文与相似来源的对应内容。','search'],['aigc','AI 率报告','查看正文分析与表达修改建议。','spark']].map(([kind,name,description,iconName])=>{
   const child=children.find(c=>c.kind===kind),ready=child?.status==='completed'&&/^[-A-Za-z0-9_]{1,120}$/.test(String(child.id||'')),incomplete=ready&&child.partial===true,failed=child&&['failed','cancelled'].includes(child.status),label=incomplete?'部分结果':ready?'已生成':failed?'未完成':'暂无报告';
   const detail=failed?(name.replace('报告','检测')+'未完成'+(child.error?'：'+esc(child.error): '，请稍后重试。')):esc(description);
   return `<article class="joint-report-card${incomplete?' is-partial':''}${!ready?' is-unavailable':''}" aria-label="${name}"><div class="joint-report-card-head"><span class="joint-report-icon joint-report-icon-${kind}" aria-hidden="true">${icon(iconName,21)}</span><span class="joint-report-badge">${label}</span></div><h4>${name}${incomplete?'（部分结果）':''}</h4><p>${detail}</p>${ready?`<a class="joint-report-link" href="#category/detection?view=${kind==='aigc'?'ai':'web'}&report=${encodeURIComponent(child.id)}">查看${kind==='aigc'?' AI 率':'重复率'}报告${incomplete?'（部分结果）':''} ${icon('arrow',16)}</a>`:'<span class="joint-report-empty">报告暂不可用</span>'}</article>`;
  }).join('');
  const note=partial?'AI 率报告包含部分未判定内容，本次联合检测未扣费。':item.error?esc(item.error):item.status==='completed'?'两份报告已准备好，可分别查看原文分析。':'已生成的报告仍可查看。';
  $('[data-joint-result]').innerHTML=`<section class="joint-result" aria-label="联合检测结果"><div class="joint-result-header"><div><span class="joint-result-eyebrow">检测结果</span><h3>${heading}</h3><p>${note}</p></div><span class="joint-result-indicator ${item.status==='completed'?'is-ready':'is-pending'}">${item.status==='completed'?(partial?'待核对':'已完成'):'未完成'}</span></div><div class="joint-report-grid">${cards}</div>${item.status!=='completed'&&!text?'<p class="joint-result-retry">重新上传论文后可以再次检测。</p>':''}</section>`;

 }
 async function read(id){await checkOwner();const next=await client.request('/combined-detections/'+encodeURIComponent(id));await checkOwner();item=next;render();}
 async function run(fn){if(busy||!current())return;busy=true;controls();try{await fn();}catch(e){if(current()){status(e.message||'暂时无法读取，请稍后重试。');if(!item){if(!intent){progress?.clear();workflow?.update({phase:'review',hasText:!!text,valid:!!text});}else if(e.status>=400&&e.status<500){intent=null;if([402,409].includes(e.status))void refreshDetectionPrice();progress?.clear();workflow?.update({phase:'review',hasText:!!text,valid:!!text});}else progress?.update({state:'recovering'});}}}finally{busy=false;controls();if(current()&&item?.status==='running'&&!timer)timer=win.setTimeout(()=>void run(()=>read(item.id)),pollInterval);}}
 async function refreshDetectionPrice(){try{const next=await client.request('/capabilities');if(!current())return;cap=next.combinedDetection||{};await priceQuote.refresh();}catch{await priceQuote.refresh();}}
 async function submit(){await checkOwner();if(!intent&&priceQuote.insufficient){const match=await client.request('/combined-detections/reuse',{text,expectedUserId:owner});await checkOwner();if(!match.item?.id)throw Error('可用积分或对应权益不足；请充值或兑换后重新检测。');item=match.item;render();status('已打开相同内容的检测记录，本次未扣费。');return;}if(!intent){const billingToken=await priceQuote.token();intent={text,title,expectedUserId:owner,idempotencyKey:crypto.randomUUID(),...detectionPriceSnapshot(cap),billingToken};}progress.update({state:'submitting'});$('[data-joint-result]').replaceChildren();workflow.update({phase:'submitting',hasText:true,valid:true,hasTask:true});status('正在提交联合检测…');item=await client.request('/combined-detections',intent);intent=null;priceQuote.invalidate();void priceQuote.refresh();await checkOwner();render();}
 const ready=(async()=>{container.innerHTML='<p role="status">正在读取联合检测服务…</p>';try{const [me,caps]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);if(!current())return;owner=me.user?.id;cap=caps.combinedDetection||{};if(!owner||!cap.ready){container.innerHTML='<section class="aigc-detection-card"><h2>联合检测暂不可用</h2><p>请登录后重试，或使用单项检测。</p></section>';return;}
 container.innerHTML=`<div data-joint-workflow></div><section class="aigc-detection-card aigc-detection-main"><header class="aigc-detection-head"><span>${icon('shield',25)}</span><div><h2>一次上传，获得两份检测报告</h2><p>同一篇论文分别检测重复率和 AI 率，独立标注原文与修改位置。</p></div></header><label class="aigc-paper-upload"><span>${icon('upload',28)}</span><strong data-joint-name>上传 DOCX 原文</strong><span>单篇不超过 20,000 字符</span><span class="aigc-upload-button">选择文件</span><input type="file" accept=".docx" data-joint-file data-upload-presentation="off" aria-label="上传联合检测原文"></label><p data-joint-status role="status" aria-live="polite">上传后即可开始检测。</p><div class="aigc-submit-bar"><div><p class="detection-submit-price" data-detection-price>正在确认本次费用…</p><button type="button" class="btn secondary" data-refresh-detection-price>刷新费用</button><small>联合检测一次计费；单项套餐次数请在对应检测中使用。失败或取消释放本次预占。</small></div><button class="btn primary" data-joint-start disabled>开始联合检测</button><button class="btn secondary" data-joint-cancel hidden>取消检测</button></div><div data-joint-progress hidden></div><div data-joint-result aria-live="polite"></div></section>`;
 workflow=createDetectionWorkflow($('[data-joint-workflow]'),{kind:'combined'});progress=createDetectionProgress($('[data-joint-progress]'));priceQuote=createDetectionQuote({request:(path,body)=>client.request(path,body),checkOwner,current,element:()=>$('[data-detection-price]'),onChange:controls,serviceKey:'detection-combined'});$('[data-refresh-detection-price]').onclick=()=>void refreshDetectionPrice();await priceQuote.refresh();workflow.update();
 $('[data-joint-file]').onchange=()=>{const file=$('[data-joint-file]').files?.[0];$('[data-joint-file]').value='';if(!file)return;void run(async()=>{validatePaperUpload(file);await checkOwner();status('正在读取论文…');const result=await importDocument(file,$('[data-joint-status]'));await checkOwner();if(Array.from(result.text||'').length>20000||(result.text||'').trim().length<50)throw Error('请上传含 50～20,000 字符正文的 DOCX。');text=result.text;title=file.name.replace(/\.docx$/i,'').slice(0,200);item=null;intent=null;stop();progress.clear();$('[data-joint-result]').replaceChildren();$('[data-joint-name]').textContent=file.name;status('原文已就绪，点击开始联合检测即可。');workflow.update({phase:'review',hasText:true,valid:true});});};
 $('[data-joint-start]').onclick=()=>void run(submit);$('[data-joint-cancel]').onclick=()=>void run(async()=>{await checkOwner();item=await client.request('/combined-detections/'+item.id+'/cancel',{expectedUserId:owner});render();});
 const recent=await client.request('/combined-detections');if(current()&&recent.items?.[0]){item=recent.items[0];render();}
 }catch(e){if(current()){if(e.status===401&&!owner)container.innerHTML=`<section class="aigc-detection-card"><h2>登录后使用联合检测</h2><p>请登录后使用；已提交的任务可登录原账户查看。</p><a class="btn primary" href="/auth.html?mode=login&amp;next=${encodeURIComponent('/workspace.html'+win.location.hash)}">登录账户</a></section>`;else container.innerHTML=`<p role="alert">${esc(e.message||'服务暂不可用')}</p>`;}}})();
 function dispose(){if(!alive)return;alive=false;stop();progress?.dispose();workflow?.dispose();client.dispose();unwatch();}unwatch=watchDocumentService(container,dispose);return{ready,dispose,canLeave:()=>!busy};
}
